@layer components {
  :where([data-control-family="transcript-divider"][data-slot="root"]) {
    --transcript-divider-foreground: var(--muted-foreground);
    --transcript-divider-line-color: var(--border);
    --transcript-divider-danger-foreground: var(--destructive-text);
    color: var(--transcript-divider-foreground);
    font-size: var(--text-caption);
  }

  :where([data-control-family="transcript-divider"][data-slot="root"])::before,

  :where([data-control-family="transcript-divider"][data-slot="root"])::after {
    background: var(--transcript-divider-line-color);
  }

  :where([data-control-family="transcript-divider"][data-slot="root"][data-tone="danger"]) {
    color: var(--transcript-divider-danger-foreground);
  }
}

@property --transcript-divider-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --transcript-divider-line-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --transcript-divider-danger-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

import type { ComponentProps, CSSProperties } from "react";

import type { TranscriptDividerProps } from "@/components/control-ui/contracts";
import type { TranscriptDividerKnobStyle } from "@/components/control-ui/knob-contracts";
import { cn } from "@/components/control-ui/lib/cn";

export function TranscriptDivider({ tone = "neutral", className, children, ...props }: TranscriptDividerProps) {
  return (
    <div
      data-control-ui="transcript-divider"
      data-control-family="transcript-divider"
      data-slot="root"
      data-tone={tone}
      className={cn("my-2 flex min-w-0 items-center before:h-px before:flex-1 after:h-px after:flex-1", className)}
      {...props}
    >
      {children != null ? <TranscriptDividerLabel>{children}</TranscriptDividerLabel> : null}
    </div>
  );
}

export type TranscriptDividerLabelProps = ComponentProps<"span"> & { style?: CSSProperties & TranscriptDividerKnobStyle };

export function TranscriptDividerLabel({ className, ...props }: TranscriptDividerLabelProps) {
  return (
    <span
      data-control-ui="transcript-divider"
      data-control-family="transcript-divider"
      data-slot="label"
      className={cn("min-w-0 truncate px-2", className)}
      {...props}
    />
  );
}
